SELECT AVG(CASE WHEN SLD012 < 7 THEN 1 ELSE 0 END) AS proportion
FROM survey
WHERE RIDRETH1 = 2 AND SDMVSTRA IS NOT NULL AND SDMVPSU IS NOT NULL;

SELECT AVG(DR1TKCAL) - AVG(DR1TKCAL) FILTER (WHERE INDFMPIR >= 2.5 AND INDFMPIR < 4.0)
FROM survey
WHERE INDFMPIR < 1.3;

SELECT (SELECT SUM(CASE WHEN RIDRETH1 = 3 AND INDFMPIR < 1.3 THEN 1 ELSE 0 END) * 1.0 / COUNT(*) FROM survey WHERE RIDRETH1 = 3) - (SELECT SUM(CASE WHEN RIDRETH1 = 5 THEN 1 ELSE 0 END) * 1.0 / COUNT(*) FROM survey WHERE RIDRETH1 = 5) AS diff_proportion
FROM survey
WHERE SEQN >= 20;

