    (
        SQRT(
            SUM(
                POWER(SMQ020 - AVG(SMQ020), 2)
            ) * COUNT(*)
        )
    ) *
    (
        SQRT(
            SUM(
                POWER(INDFMPIR - AVG(INDFMPIR), 2)
            ) * COUNT(*)
        )
    ) AS correlation
FROM survey
WHERE SEQN > 1 AND SMQ020 IN (1, 0) AND SMQ040 <> 1 AND WTMEC2YR IS NOT NULL;
